function key(h,a){return `${h}:${a.slot}:${a.level}:${a.name}`}
function normalize(s){return String(s||'').toLowerCase().replace(/[’‘]/g,"'").replace(/[^a-z0-9' ]+/g,' ').replace(/\s+/g,' ').trim()}
function legacyAbilities(h){let L=Math.min(12,Math.max(1,level(h))), rows=LEGACY?.[h]?.[String(L)]||[];return rows.map(x=>({...x,source:'legacy'}))}
